const S={concerts:[],filtered:[],sets:null,stats:null,changes:[],page:0,size:40};
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
async function load(){const [c,st,ch,state]=await Promise.all(['concerts.json','stats.json','changelog.json','state.json'].map(f=>fetch('data/'+f).then(r=>r.json())));S.concerts=c;S.stats=st;S.changes=ch.reverse();S.filtered=[...c].reverse();init();render();}
function init(){const years=[...new Set(S.concerts.map(c=>c.year))].sort((a,b)=>b-a), countries=[...new Set(S.concerts.map(c=>c.country).filter(Boolean))].sort(), artists=[...new Set(S.concerts.map(c=>c.artist).filter(Boolean))].sort();years.forEach(v=>$('#year').insertAdjacentHTML('beforeend',`<option>${v}</option>`));countries.forEach(v=>$('#country').insertAdjacentHTML('beforeend',`<option>${esc(v)}</option>`));artists.forEach(v=>$('#artist').insertAdjacentHTML('beforeend',`<option>${esc(v)}</option>`));['q','year','country','artist','status'].forEach(id=>$('#'+id).addEventListener(id==='q'?'input':'change',filter));$('#reset').onclick=()=>{['q','year','country','artist','status'].forEach(id=>$('#'+id).value='');filter()};$('#prev').onclick=()=>{S.page=Math.max(0,S.page-1);renderCards()};$('#next').onclick=()=>{S.page=Math.min(Math.ceil(S.filtered.length/S.size)-1,S.page+1);renderCards()};document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab,.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#'+b.dataset.view).classList.add('active')});document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});}
function filter(){let q=$('#q').value.toLowerCase(),y=$('#year').value,c=$('#country').value,a=$('#artist').value,s=$('#status').value;S.filtered=S.concerts.filter(x=>(!q||[x.city,x.venue,x.country,x.event,x.tour,x.artist].join(' ').toLowerCase().includes(q))&&(!y||String(x.year)===y)&&(!c||x.country===c)&&(!a||x.artist===a)&&(!s||(x.setlistStatus||'Unknown')===s)).reverse();S.page=0;renderCards()}
function render(){const y=Object.keys(S.stats.years), latest=Math.max(...y.map(Number)), earliest=Math.min(...y.map(Number));$('#kpis').innerHTML=[[S.stats.concerts,'Concerts / événements'],[`${earliest}–${latest}`,'Période'],[Object.keys(S.stats.years).length,'Années'],[S.stats.setlistEntries.toLocaleString('fr-FR'),'Entrées de setlist']].map(x=>`<div class=kpi><b>${x[0]}</b><span>${x[1]}</span></div>`).join('');$('#syncText').textContent=S.stats.lastSync?`Synchronisé ${new Date(S.stats.lastSync).toLocaleString('fr-FR')}`:'Archive V4';renderCards();ranking('#topSongs',S.stats.songs);ranking('#topCountries',S.stats.countries);renderYears();renderChanges()}
function renderCards(){let pages=Math.max(1,Math.ceil(S.filtered.length/S.size));S.page=Math.min(S.page,pages-1);$('#count').textContent=S.filtered.length.toLocaleString('fr-FR');$('#pageInfo').textContent=`— page ${S.page+1}/${pages}`;let list=S.filtered.slice(S.page*S.size,(S.page+1)*S.size);$('#cards').innerHTML=list.map(c=>`<article class=card data-id="${esc(c.id)}"><div class=cardtop><div class=date>${fmt(c.date)}</div><span class="badge ${(c.setlistStatus||'').toLowerCase()}">${esc(c.setlistStatus||'Unknown')}</span></div><div class=place>${esc(c.city||'Lieu inconnu')}, ${esc(c.country||'')}</div><div class=venue>${esc(c.venue||'')}</div><div class=meta>${c.artist?`<span>${esc(c.artist)}</span>`:''}${c.tour?`<span>${esc(c.tour)}</span>`:''}${c.songsPlayed?`<span>${c.songsPlayed} titres</span>`:''}${c.setLengthMin?`<span>${c.setLengthMin} min</span>`:''}</div></article>`).join('');document.querySelectorAll('.card').forEach(x=>x.onclick=()=>detail(x.dataset.id))}
function fmt(d){if(!d)return'';let [y,m,day]=d.split('-');return day&&m&&!d.includes('xx')?`${day}.${m}.${y}`:d}
async function detail(id){let c=S.concerts.find(x=>x.id===id);if(!S.sets)S.sets=await fetch('data/setlists.json').then(r=>r.json());let songs=S.sets.filter(x=>x.concertId===id||x.date===c.date),groups={};songs.forEach(s=>(groups[s.section||'Set']??=[]).push(s));let setHtml=Object.entries(groups).map(([g,a])=>`<div class=setgroup><h4>${esc(g)}</h4><ol>${a.sort((x,y)=>(x.position||0)-(y.position||0)).map(s=>`<li>${esc(s.song)}</li>`).join('')}</ol></div>`).join('')||'<p class=sub>Setlist non disponible.</p>';$('#detail').innerHTML=`<div class=eyebrow style="color:#444">${esc(c.artist||'THE CURE')} · ${esc(c.year)}</div><h2>${esc(c.city||'')}${c.country?', '+esc(c.country):''}</h2><div class=sub>${esc(c.venue||'')} ${c.event?'· '+esc(c.event):''}</div><div class=facts>${[['Date',fmt(c.date)],['Tournée',c.tour],['Durée',c.setLengthMin?c.setLengthMin+' min':null],['Titres',c.songsPlayed],['Affluence',c.attendance],['Capacité',c.concertCapacity],['Horaire',c.setTime],['Sold out',c.soldOut],['Adresse',c.venueAddress]].filter(x=>x[1]).map(x=>`<div class=fact><b>${esc(x[0])}</b><br>${esc(x[1])}</div>`).join('')}</div><h3>Setlist</h3><div class=setlist>${setHtml}</div><p class="source-links">${c.sourceUrl?`<a href="${esc(c.sourceUrl)}" target=_blank rel=noopener>Cure Concerts Guide ↗</a>`:''}${c.setlistFmUrl?` · <a href="${esc(c.setlistFmUrl)}" target=_blank rel=noopener>setlist.fm ↗</a>`:''}</p>`;$('#modal').classList.add('open');$('#modal').setAttribute('aria-hidden','false')}
function closeModal(){$('#modal').classList.remove('open');$('#modal').setAttribute('aria-hidden','true')}
function ranking(sel,data){$(sel).innerHTML=data.slice(0,20).map(([n,v],i)=>`<div class=row><span>${i+1}. ${esc(n)}</span><b>${v}</b></div>`).join('')}
function renderYears(){let vals=Object.entries(S.stats.years),max=Math.max(...vals.map(x=>x[1]));$('#yearBars').innerHTML=vals.map(([y,v])=>`<div class=bar title="${y}: ${v}" style="height:${Math.max(3,v/max*100)}%"></div>`).join('')}
function renderChanges(){$('#changeList').innerHTML=S.changes.slice(0,150).map(x=>`<div class=change><b>${esc(x.type)}</b> · ${esc(x.date||'')} · <code>${esc(x.field||'')}</code><br><span class=muted>${esc(x.old??'∅')} → ${esc(x.new??'∅')} · ${new Date(x.timestamp).toLocaleString('fr-FR')}</span></div>`).join('')||'<p class=muted>Aucun changement enregistré depuis la création de la V4.</p>'}
load().catch(e=>document.body.insertAdjacentHTML('afterbegin',`<div style="padding:12px;background:#8b1d2c;color:white">Erreur de chargement: ${esc(e.message)}</div>`));
